{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-LACBlq/src/address.js","content":"// Cell address handling: columns A..Z, AA..ZZ (bijective base 26, max 2 letters),
// rows 1..999 (1 to 3 digits).

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

// Convert a positive integer to bijective base-26 letters (A, B, ..., Z, AA, ...).
export function colIndexToLetters(idx) {
  let n = idx
  let letters = ''
  while (n > 0) {
    n -= 1
    letters = String.fromCharCode(65 + (n % 26)) + letters
    n = Math.floor(n / 26)
  }
  return letters
}

export function lettersToColIndex(letters) {
  let idx = 0
  for (const ch of letters.toUpperCase()) {
    idx = idx * 26 + (ch.charCodeAt(0) - 64)
  }
  return idx
}

// Parse a bare word (already known to be [A-Za-z][A-Za-z0-9]*) as an address.
// Returns { valid, col, row } - valid is false when the word is not exactly
// one or two letters followed by one to three digits naming a row >= 1.
export function parseAddressWord(word) {
  const m = ADDR_RE.exec(word)
  if (!m) return { valid: false }
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const col = lettersToColIndex(m[1])
  return { valid: true, col, row }
}

export function canonicalAddress(col, row) {
  return `${colIndexToLetters(col)}${row}`
}
"}

