{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-LACBlq/src/parser.js","content":"import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADD_OPS = new Set(['+', '-'])
const MUL_OPS = new Set(['*', '/'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  advance() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (t.type !== type) throw new ParseError(`expected ${type} but found ${t.type}`)
    return this.advance()
  }

  parseFormula() {
    const expr = this.parseComparison()
    this.expect('eof')
    return expr
  }

  parseComparison() {
    let left = this.parseAdd()
    while (this.peek().type === 'op' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.advance().value
      const right = this.parseAdd()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseAdd() {
    let left = this.parseMul()
    while (this.peek().type === 'op' && ADD_OPS.has(this.peek().value)) {
      const op = this.advance().value
      const right = this.parseMul()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseMul() {
    let left = this.parsePow()
    while (this.peek().type === 'op' && MUL_OPS.has(this.peek().value)) {
      const op = this.advance().value
      const right = this.parsePow()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parsePow() {
    const left = this.parseUnary()
    if (this.peek().type === 'op' && this.peek().value === '^') {
      this.advance()
      const right = this.parsePow()
      return { type: 'BinOp', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'op' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.advance().value
      const operand = this.parseUnary()
      return { type: 'UnaryOp', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'num') {
      this.advance()
      return { type: 'Num', value: parseFloat(t.value) }
    }
    if (t.type === 'lparen') {
      this.advance()
      const expr = this.parseComparison()
      this.expect('rparen')
      return expr
    }
    if (t.type === 'word') {
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') { this.advance(); return { type: 'Bool', value: true } }
      if (upper === 'FALSE') { this.advance(); return { type: 'Bool', value: false } }
      if (this.peek(1) && this.peek(1).type === 'lparen') {
        this.advance()
        this.advance()
        const args = this.parseArgList()
        this.expect('rparen')
        return { type: 'Call', name: upper, args }
      }
      this.advance()
      return { type: 'Address', word: t.value }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }

  parseArgList() {
    const args = []
    if (this.peek().type === 'rparen') return args
    args.push(this.parseArg())
    while (this.peek().type === 'comma') {
      this.advance()
      args.push(this.parseArg())
    }
    return args
  }

  parseArg() {
    if (this.peek().type === 'word' && this.peek(1) && this.peek(1).type === 'colon') {
      const a = this.advance().value
      this.advance() // colon
      const bTok = this.peek()
      if (bTok.type !== 'word') throw new ParseError('expected address after colon')
      const b = this.advance().value
      return { type: 'Range', a, b }
    }
    return this.parseComparison()
  }
}

export function parseFormula(text) {
  const tokens = tokenize(text)
  const parser = new Parser(tokens)
  return parser.parseFormula()
}

export { LexError }
"}

