// Parses the raw sheet text into a Map from canonical address ("A1") to
// { content, line, col, row }, preserving nothing about declaration order
// (callers sort by column/row as needed).
export function parseSheet(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let idx = 0; idx < lines.length; idx += 1) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    let addr
    let content
    let wsIdx = -1
    for (let i = 0; i < stripped.length; i += 1) {
      if (stripped[i] === ' ' || stripped[i] === '\t') { wsIdx = i; break }
    }
    if (wsIdx === -1) {
      addr = stripped
      content = ''
    } else {
      addr = stripped.slice(0, wsIdx)
      let rest = wsIdx
      while (rest < stripped.length && (stripped[rest] === ' ' || stripped[rest] === '\t')) rest += 1
      content = stripped.slice(rest)
    }

    const m = ADDR_RE.exec(addr)
    let row = m ? parseInt(m[2], 10) : -1
    if (!m || row < 1) {
      throw new SheetError(lineNo, `invalid cell address ${addr}`)
    }
    const col = lettersToColIndex(m[1])
    const canonical = `${m[1].toUpperCase()}${row}`

    if (cells.has(canonical)) {
      throw new SheetError(lineNo, `cell ${canonical} is declared twice`)
    }
    cells.set(canonical, { content, line: lineNo, col, row })
  }

  return cells
}
