{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-LACBlq/src/values.js","content":"// Value constructors and helpers.

export const mkNum = (v) => ({ type: 'num', value: v })
export const mkText = (v) => ({ type: 'text', value: v })
export const mkBool = (v) => ({ type: 'bool', value: v })
export const mkErr = (v) => ({ type: 'err', value: v })

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function parseLiteral(content) {
  if (content === '') return mkNum(0)
  if (ERROR_TOKENS.has(content)) return mkErr(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return mkNum(parseFloat(content))
  return mkText(content)
}

// Convert a value to a number for arithmetic; returns null when the value
// cannot be read as a number (text). Callers must handle 'err' beforehand.
export function numOf(v) {
  if (v.type === 'num') return v.value
  if (v.type === 'bool') return v.value ? 1 : 0
  if (v.type === 'text') return null
  return null
}

export function formatNumber(n) {
  const rounded = Number(n.toPrecision(10))
  return rounded.toString()
}

export function formatValue(v) {
  switch (v.type) {
    case 'num': return formatNumber(v.value)
    case 'err': return v.value
    case 'bool': return v.value ? 'TRUE' : 'FALSE'
    case 'text': return v.value
    default: throw new Error('unknown value type')
  }
}

function typeRank(v) {
  if (v.type === 'num') return 0
  if (v.type === 'text') return 1
  if (v.type === 'bool') return 2
  return 3
}

export function compareValues(l, r) {
  const rl = typeRank(l)
  const rr = typeRank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'num') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'bool') {
    const lv = l.value ? 1 : 0
    const rv = r.value ? 1 : 0
    return lv - rv
  }
  return 0
}
"}

