/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Engine } from './engine.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
    return
  }

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const engine = new Engine(cells)

  const addrs = [...cells.entries()]
    .map(([canonical, cell]) => ({ canonical, col: cell.col, row: cell.row }))
    .sort((a, b) => (a.col - b.col) || (a.row - b.row))

  const out = []
  if (mode === 'values') {
    for (const { canonical } of addrs) {
      const value = engine.evaluateCell(canonical)
      out.push(`${canonical}=${formatValue(value)}\n`)
    }
  } else {
    for (const { canonical } of addrs) {
      const deps = engine.collectDeps(canonical)
      const suffix = deps.length ? ` ${deps.join(' ')}` : ''
      out.push(`${canonical}:${suffix}\n`)
    }
  }
  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

